-- Replace the platform-smoke-test items with a guided first unit for absolute beginners.
-- Keep the original exercise IDs so any existing learner history remains attached.

UPDATE learning_exercises
SET exercise_number = CASE id
  WHEN 'a1-01-ex1' THEN 6
  WHEN 'a1-01-ex2' THEN 7
  WHEN 'a1-01-ex3' THEN 8
END
WHERE id IN ('a1-01-ex1', 'a1-01-ex2', 'a1-01-ex3');

UPDATE learning_lessons SET content_json = '{"objective":"Reconocer el nombre de algunas letras y pedir o dar el deletreo de un nombre.","sections":[{"type":"learn","title":"Las letras tienen nombre y sonido","body":"En inglés, la letra A se llama /eɪ/ (aproximadamente, «ei»), E se llama /iː/ («ii»), I se llama /aɪ/ («ai») y J se llama /dʒeɪ/ («yei»). Son nombres de letras, no palabras. Escucha y repite cada una despacio."},{"type":"learn","title":"Deletrea tu nombre","body":"Para preguntar cómo se escribe un nombre: “How do you spell your name?” Para responder, di las letras separadas: “A-N-A”. En una conversación también puedes decir: “My name is Ana”."},{"type":"examples","title":"Modelo","body":"A: Hello. What’s your name? B: My name is Leo. A: How do you spell Leo? B: L-E-O. A: Thank you. B: You’re welcome."},{"type":"practice","title":"Practica paso a paso","body":"Primero reconoce nombres de letras; después identifica preguntas y respuestas de deletreo. Lee cada situación completa antes de elegir."}],"reviewEnabled":true}' WHERE id = 'a1-01';
UPDATE learning_lessons SET content_json = '{"objective":"Saludar a alguien en distintos momentos del día y responder de forma natural.","sections":[{"type":"learn","title":"Tres saludos útiles","body":"“Hello” sirve en casi cualquier situación. “Hi” es más informal. “Good morning” se usa por la mañana; “Good afternoon”, por la tarde. No hace falta traducir palabra por palabra: aprende cada expresión como un bloque."},{"type":"examples","title":"Al llegar","body":"A: Good morning, Ana. B: Good morning, Leo. / A: Hi! B: Hello!"},{"type":"learn","title":"Una respuesta sencilla","body":"Al responder a un saludo, puedes repetirlo o decir “Hi” o “Hello”. Si acabas de conocer a alguien, “Nice to meet you” significa «Encantado/a de conocerte»."},{"type":"practice","title":"Practica en contexto","body":"Elige el saludo que encaja con la hora y la relación entre las personas. Después completa intercambios cortos."}],"reviewEnabled":true}' WHERE id = 'a1-02';
UPDATE learning_lessons SET content_json = '{"objective":"Usar please y thank you para pedir algo con cortesía y agradecerlo.","sections":[{"type":"learn","title":"Pedir con cortesía","body":"“Please” hace que una petición suene educada: “A coffee, please” («Un café, por favor»). También puedes decir “Please, help me”."},{"type":"learn","title":"Dar las gracias","body":"Di “Thank you” o “Thanks” cuando alguien te ayuda o te da algo. Una respuesta habitual es “You’re welcome” («De nada»)."},{"type":"examples","title":"En una cafetería","body":"A: Tea or coffee? B: Tea, please. A: Here you are. B: Thank you. A: You’re welcome."},{"type":"practice","title":"Practica en contexto","body":"Decide qué dirías al pedir, recibir algo o responder a un agradecimiento. Fíjate en quién habla y qué acaba de ocurrir."}],"reviewEnabled":true}' WHERE id = 'a1-03';
UPDATE learning_lessons SET content_json = '{"objective":"Decir tu nombre y preguntar el nombre de otra persona con dos estructuras básicas.","sections":[{"type":"learn","title":"Presentarte","body":"Puedes decir “I’m Ana” («Soy Ana / Me llamo Ana») o “My name is Ana” («Me llamo Ana»). “I’m” es la forma corta de “I am”. Cambia Ana por tu nombre."},{"type":"learn","title":"Preguntar el nombre","body":"“What’s your name?” significa «¿Cómo te llamas?». “What’s” es la forma corta de “What is”. Responde con “I’m…” o “My name is…”."},{"type":"examples","title":"Modelo","body":"A: Hello. I’m Sara. What’s your name? B: I’m Pablo. A: Nice to meet you, Pablo. B: Nice to meet you, too."},{"type":"practice","title":"Practica con nombres","body":"Completa presentaciones breves, elige respuestas que encajan y distingue preguntas de respuestas."}],"reviewEnabled":true}' WHERE id = 'a1-04';
UPDATE learning_lessons SET content_json = '{"objective":"Preguntar cómo está alguien, responder con una frase corta y devolver la pregunta.","sections":[{"type":"learn","title":"La pregunta","body":"“How are you?” significa «¿Cómo estás?». Es un saludo frecuente. No pregunta el nombre ni el lugar donde vives."},{"type":"learn","title":"Respuestas breves","body":"Puedes responder “I’m fine, thanks” («Estoy bien, gracias»), “I’m good, thanks” o “I’m OK”. “I’m” significa “I am”."},{"type":"examples","title":"Devuelve la pregunta","body":"A: Hi, Sara. How are you? B: I’m fine, thanks. And you? A: I’m good, thank you."},{"type":"practice","title":"Practica el intercambio","body":"Elige respuestas breves y completas intercambios. “And you?” devuelve la pregunta a la otra persona."}],"reviewEnabled":true}' WHERE id = 'a1-05';
UPDATE learning_lessons SET content_json = '{"objective":"Mantener una conversación de cuatro turnos: saludar, presentarte, preguntar y despedirte.","sections":[{"type":"learn","title":"Une lo que ya sabes","body":"Una conversación inicial puede seguir este orden: saludo → nombre → pregunta sobre cómo está la otra persona → despedida. No necesitas crear frases largas: usa bloques cortos."},{"type":"examples","title":"Conversación modelo","body":"A: Hello! I’m Ana. What’s your name? B: Hi, Ana. I’m Leo. A: Nice to meet you. How are you? B: I’m fine, thanks. And you? A: I’m good, thank you. Goodbye! B: Bye!"},{"type":"learn","title":"Despedidas","body":"“Goodbye” es una despedida neutral. “Bye” es más informal. “See you later” significa «Hasta luego». “Good night” suele decirse al despedirse por la noche, no como saludo al llegar."},{"type":"practice","title":"Resuelve situaciones","body":"Completa diálogos y elige la siguiente frase que mantiene el sentido de la conversación. Las expresiones se reutilizan de las lecciones anteriores."}],"reviewEnabled":true}' WHERE id = 'a1-06';

-- Lesson 1 already has five authored items. Improve them and reuse the three legacy
-- smoke-test IDs as a short additional review instead of deleting learner history.
UPDATE learning_exercises SET exercise_number = 1, prompt = 'Quieres saber cómo se escribe el nombre de Ana. ¿Qué pregunta haces?', options_json = '["How are you?","How do you spell your name?","What is your name?","Where are you?"]', answer_json = '{"correct":"How do you spell your name?"}', explanation = '“How do you spell your name?” pide que la persona diga su nombre letra por letra. “What is your name?” pregunta cuál es su nombre.' WHERE id = 'a1-01-ex-01';
UPDATE learning_exercises SET exercise_number = 2, prompt = 'Leo responde: “L-E-O”. ¿Qué está haciendo?', options_json = '["Diciendo cómo se siente","Deletreando su nombre","Dando las gracias","Despidiéndose"]', answer_json = '{"correct":"Deletreando su nombre"}', explanation = 'Al deletrear, se dicen las letras por separado: L-E-O.' WHERE id = 'a1-01-ex-02';
UPDATE learning_exercises SET exercise_number = 3, prompt = 'Completa la presentación: “My ___ is Ana.”', options_json = '["name","spell","letter","morning"]', answer_json = '{"correct":"name"}', explanation = '“My name is Ana” significa «Me llamo Ana». “Name” es «nombre».' WHERE id = 'a1-01-ex-03';
UPDATE learning_exercises SET exercise_number = 4, prompt = '¿Cuál responde correctamente a “How do you spell Leo?”', options_json = '["I’m fine, thanks.","L-E-O.","Good morning.","My name is Leo."]', answer_json = '{"correct":"L-E-O."}', explanation = 'La pregunta pide deletrear. La respuesta da las letras del nombre: L-E-O.' WHERE id = 'a1-01-ex-04';
UPDATE learning_exercises SET exercise_number = 5, prompt = 'Lee el intercambio. ¿Qué dice Ana para indicar su nombre? “Hello. My name is Ana.”', options_json = '["Hello","My name is Ana","Goodbye","How do you spell it?"]', answer_json = '{"correct":"My name is Ana"}', explanation = '“My name is Ana” presenta el nombre de Ana. “Hello” es el saludo.' WHERE id = 'a1-01-ex-05';
UPDATE learning_exercises SET exercise_number = 6, prompt = 'La letra A inglesa se llama aproximadamente…', options_json = '["/æ/ (a)","/eɪ/ (ei)","/iː/ (ii)","/aɪ/ (ai)"]', answer_json = '{"correct":"/eɪ/ (ei)"}', explanation = 'El nombre de la letra A en inglés se pronuncia /eɪ/, parecido a «ei». Es el nombre de la letra, no siempre el sonido que hace dentro de una palabra.' WHERE id = 'a1-01-ex1';
UPDATE learning_exercises SET exercise_number = 7, prompt = '¿Qué frase significa «Me llamo Leo»?', options_json = '["How do you spell Leo?","My name is Leo.","How are you, Leo?","Thank you, Leo."]', answer_json = '{"correct":"My name is Leo."}', explanation = '“My name is Leo” se usa para decir tu nombre. “How do you spell Leo?” pregunta cómo se escribe.' WHERE id = 'a1-01-ex2';
UPDATE learning_exercises SET exercise_number = 8, prompt = 'Completa el diálogo: A: “What’s your name?” B: “___”', options_json = '["I’m Sara.","I’m fine, thanks.","Goodbye.","You’re welcome."]', answer_json = '{"correct":"I’m Sara."}', explanation = '“What’s your name?” pregunta el nombre. “I’m Sara” es una respuesta natural; “I’m fine” responde a “How are you?”.' WHERE id = 'a1-01-ex3';

INSERT INTO learning_exercises (id, lesson_id, exercise_number, exercise_type, prompt, options_json, answer_json, explanation) VALUES
('a1-02-ex-01', 'a1-02', 1, 'multiple_choice', 'Llegas a clase a las 9:00 de la mañana. ¿Qué saludo encaja mejor?', '["Good morning!","Good night!","Goodbye!","You’re welcome!"]', '{"correct":"Good morning!"}', '“Good morning” se usa por la mañana para saludar, no para despedirse.'),
('a1-02-ex-02', 'a1-02', 2, 'multiple_choice', 'Una compañera te dice “Hi!”. ¿Cuál es una respuesta natural?', '["Hi!","How do you spell it?","Good night!","Thank you."]', '{"correct":"Hi!"}', 'Puedes responder a “Hi!” repitiendo “Hi!” o diciendo “Hello!”.'),
('a1-02-ex-03', 'a1-02', 3, 'multiple_choice', '¿Qué saludo es informal y corto?', '["Hi","Good afternoon","Goodbye","You’re welcome"]', '{"correct":"Hi"}', '“Hi” es un saludo informal. “Good afternoon” es un saludo más específico y “Goodbye” es una despedida.'),
('a1-02-ex-04', 'a1-02', 4, 'multiple_choice', 'Te presentan a alguien por primera vez. ¿Qué puedes decir?', '["Nice to meet you.","Good night.","How do you spell it?","I’m fine, thanks."]', '{"correct":"Nice to meet you."}', '“Nice to meet you” significa «Encantado/a de conocerte» y se usa al conocer a alguien.'),
('a1-02-ex-05', 'a1-02', 5, 'multiple_choice', 'Completa: A: “Good afternoon, Marta.” B: “___, Alex.”', '["Good afternoon","Goodbye","Thank you","You’re welcome"]', '{"correct":"Good afternoon"}', 'Marta devuelve el mismo saludo: “Good afternoon”.'),
('a1-03-ex-01', 'a1-03', 1, 'multiple_choice', 'Pides un té en una cafetería. ¿Qué opción suena educada?', '["Tea, please.","Tea, goodbye.","Tea, how are you?","Tea, you’re welcome."]', '{"correct":"Tea, please."}', '“Please” hace educada la petición: “Tea, please” («Un té, por favor»).'),
('a1-03-ex-02', 'a1-03', 2, 'multiple_choice', 'Alguien te entrega un libro. ¿Qué dices?', '["Thank you.","Good morning.","How do you spell it?","Goodbye."]', '{"correct":"Thank you."}', '“Thank you” significa «Gracias» y se dice al recibir algo o ayuda.'),
('a1-03-ex-03', 'a1-03', 3, 'multiple_choice', 'Tú dices “Thank you”. ¿Qué puede responder la otra persona?', '["You’re welcome.","What’s your name?","Good night.","I’m Ana."]', '{"correct":"You’re welcome."}', '“You’re welcome” significa «De nada» y responde a “Thank you”.'),
('a1-03-ex-04', 'a1-03', 4, 'multiple_choice', 'Elige la petición completa: “Un café, por favor.”', '["A coffee, please.","A coffee, thank you.","A coffee, goodbye.","A coffee, I’m fine."]', '{"correct":"A coffee, please."}', 'Al pedir algo puedes poner “please” al final: “A coffee, please”.'),
('a1-03-ex-05', 'a1-03', 5, 'multiple_choice', 'Completa: A: “Here you are.” B: “___”', '["Thank you.","How are you?","Good night.","What’s your name?"]', '{"correct":"Thank you."}', '“Here you are” se dice al entregar algo. La respuesta apropiada es “Thank you”.'),
('a1-04-ex-01', 'a1-04', 1, 'multiple_choice', 'Acabas de conocer a Alex. ¿Cómo dices «Me llamo Sara»?', '["I’m Sara.","How are you, Sara?","You’re welcome, Sara.","Goodbye, Sara."]', '{"correct":"I’m Sara."}', '“I’m Sara” es la forma corta de “I am Sara” y sirve para presentarte.'),
('a1-04-ex-02', 'a1-04', 2, 'multiple_choice', '¿Qué pregunta haces para saber el nombre de otra persona?', '["What’s your name?","How are you?","How do you spell it?","Good morning?"]', '{"correct":"What’s your name?"}', '“What’s your name?” significa «¿Cómo te llamas?». “How do you spell it?” pregunta cómo se escribe algo.'),
('a1-04-ex-03', 'a1-04', 3, 'multiple_choice', 'Completa: “My ___ is Diego.”', '["name","fine","morning","spell"]', '{"correct":"name"}', '“My name is Diego” significa «Me llamo Diego». “Name” es «nombre».'),
('a1-04-ex-04', 'a1-04', 4, 'multiple_choice', 'Elige una respuesta adecuada: A: “What’s your name?” B: “___”', '["My name is Eva.","I’m fine, thanks.","Good night.","You’re welcome."]', '{"correct":"My name is Eva."}', 'La pregunta pide el nombre. “My name is Eva” responde con el nombre.'),
('a1-04-ex-05', 'a1-04', 5, 'multiple_choice', '¿Qué significa “Nice to meet you”?', '["Encantado/a de conocerte.","¿Cómo te llamas?","Estoy bien, gracias.","Hasta luego."]', '{"correct":"Encantado/a de conocerte."}', '“Nice to meet you” se dice al conocer a alguien. Puedes responder “Nice to meet you, too”.'),
('a1-05-ex-01', 'a1-05', 1, 'multiple_choice', '¿Qué pregunta significa «¿Cómo estás?»?', '["How are you?","What’s your name?","How do you spell it?","Where is it?"]', '{"correct":"How are you?"}', '“How are you?” pregunta cómo está la persona; no pregunta su nombre.'),
('a1-05-ex-02', 'a1-05', 2, 'multiple_choice', 'Elige una respuesta natural: A: “How are you?” B: “___”', '["I’m fine, thanks.","My name is Ben.","Goodbye.","It’s B-E-N."]', '{"correct":"I’m fine, thanks."}', '“I’m fine, thanks” significa «Estoy bien, gracias» y responde a “How are you?”.'),
('a1-05-ex-03', 'a1-05', 3, 'multiple_choice', '¿Qué expresión devuelve la pregunta «¿Y tú?»?', '["And you?","Thank you.","You’re welcome.","See you later."]', '{"correct":"And you?"}', 'Después de responder puedes preguntar “And you?” para saber cómo está la otra persona.'),
('a1-05-ex-04', 'a1-05', 4, 'multiple_choice', 'Completa el intercambio: A: “I’m good, thanks. ___?” B: “I’m fine.”', '["And you","What’s your name","Good night","How do you spell it"]', '{"correct":"And you"}', '“And you?” devuelve la pregunta. La otra persona responde “I’m fine”.'),
('a1-05-ex-05', 'a1-05', 5, 'multiple_choice', '¿Cuál es la forma corta de “I am fine”?', '["I’m fine.","My fine.","I fine.","I’m name."]', '{"correct":"I’m fine."}', '“I’m” es la forma corta de “I am”. Por eso “I’m fine” es correcto.'),
('a1-06-ex-01', 'a1-06', 1, 'multiple_choice', 'Elige el inicio más natural de una primera conversación.', '["A: Hello! B: Hi!","A: You’re welcome. B: Thank you.","A: Goodbye! B: Good morning!","A: How do you spell it? B: I’m fine."]', '{"correct":"A: Hello! B: Hi!"}', 'Una conversación suele empezar con un saludo: “Hello” y “Hi” encajan.'),
('a1-06-ex-02', 'a1-06', 2, 'multiple_choice', 'A: “Hi, I’m Ana. What’s your name?” ¿Qué respuesta encaja?', '["B: I’m Leo. Nice to meet you.","B: I’m fine, thanks. You’re welcome.","B: Good night. Tea, please.","B: L-E-O. Goodbye, morning."]', '{"correct":"B: I’m Leo. Nice to meet you."}', 'Ana pregunta el nombre. Leo se presenta y responde a la presentación con “Nice to meet you”.'),
('a1-06-ex-03', 'a1-06', 3, 'multiple_choice', 'A: “How are you?” B: “I’m fine, thanks.” ¿Qué puede preguntar B después?', '["And you?","What’s your name?","How do you spell it?","Goodbye?"]', '{"correct":"And you?"}', 'Después de responder cómo está, B puede devolver la pregunta con “And you?”.'),
('a1-06-ex-04', 'a1-06', 4, 'multiple_choice', 'La conversación termina y quieres despedirte de manera informal. ¿Qué dices?', '["Bye!","Good morning!","How are you?","My name is Ana."]', '{"correct":"Bye!"}', '“Bye” es una despedida informal. “Good morning” es un saludo.'),
('a1-06-ex-05', 'a1-06', 5, 'multiple_choice', 'Completa el final: A: “Thank you.” B: “You’re welcome. ___”', '["See you later!","What’s your name?","I’m fine, thanks.","How do you spell it?"]', '{"correct":"See you later!"}', '“See you later” significa «Hasta luego» y funciona como despedida.' )
ON CONFLICT(id) DO UPDATE SET
  lesson_id = excluded.lesson_id,
  exercise_number = excluded.exercise_number,
  exercise_type = excluded.exercise_type,
  prompt = excluded.prompt,
  options_json = excluded.options_json,
  answer_json = excluded.answer_json,
  explanation = excluded.explanation;

